@Test
public void testPartUploadStreamContentLength() throws IOException, OS3Exception {
    HttpHeaders headers = mock(HttpHeaders.class);
    when(headers.getHeaderString(X_AMZ_CONTENT_SHA256)).thenReturn("mockSignature");
    ObjectEndpoint objectEndpoint = EndpointBuilder.newObjectEndpointBuilder().setHeaders(headers).setClient(client).build();
    String keyName = UUID.randomUUID().toString();
    String chunkedContent = "0a;chunk-signature=signature\r\n" + "1234567890\r\n" + "05;chunk-signature=signature\r\n" + "abcde\r\n";
    when(headers.getHeaderString("x-amz-content-sha256")).thenReturn("STREAMING-AWS4-HMAC-SHA256-PAYLOAD");
    when(headers.getHeaderString(DECODED_CONTENT_LENGTH_HEADER)).thenReturn("15");
    Response response = objectEndpoint.initializeMultipartUpload(OzoneConsts.S3_BUCKET, keyName);
    MultipartUploadInitiateResponse multipartUploadInitiateResponse = (MultipartUploadInitiateResponse) response.getEntity();
    assertNotNull(multipartUploadInitiateResponse.getUploadID());
    String uploadID = multipartUploadInitiateResponse.getUploadID();
    long contentLength = chunkedContent.length();
    objectEndpoint.put(OzoneConsts.S3_BUCKET, keyName, contentLength, 1, uploadID, null, null, new ByteArrayInputStream(chunkedContent.getBytes(UTF_8)));
    assertContentLength(uploadID, keyName, 15);
}

