public void testPartUploadMessageDigestResetDuringException() throws IOException, OS3Exception {
    OzoneClient clientStub = new OzoneClientStub();
    clientStub.getObjectStore().createS3Bucket(OzoneConsts.S3_BUCKET);
    HttpHeaders headers = mock(HttpHeaders.class);
    when(headers.getHeaderString(X_AMZ_CONTENT_SHA256)).thenReturn("mockSignature");
    when(headers.getHeaderString(STORAGE_CLASS_HEADER)).thenReturn("STANDARD");
    ObjectEndpoint objectEndpoint = EndpointBuilder.newObjectEndpointBuilder().setHeaders(headers).setClient(clientStub).build();
    objectEndpoint = spy(objectEndpoint);
    Response response = objectEndpoint.initializeMultipartUpload(OzoneConsts.S3_BUCKET, OzoneConsts.KEY);
    MultipartUploadInitiateResponse multipartUploadInitiateResponse = (MultipartUploadInitiateResponse) response.getEntity();
    assertNotNull(multipartUploadInitiateResponse.getUploadID());
    String uploadID = multipartUploadInitiateResponse.getUploadID();
    assertEquals(200, response.getStatus());
    MessageDigest messageDigest = mock(MessageDigest.class);
    try (MockedStatic<IOUtils> mocked = mockStatic(IOUtils.class)) {
        // Add the mocked methods only during the copy request
        when(objectEndpoint.getMessageDigestInstance()).thenReturn(messageDigest);
        mocked.when(() -> IOUtils.copyLarge(any(InputStream.class), any(OutputStream.class), anyLong(), anyLong(), any(byte[].class))).thenThrow(IOException.class);
        String content = "Multipart Upload";
        ByteArrayInputStream body = new ByteArrayInputStream(content.getBytes(UTF_8));
        try {
            objectEndpoint.put(OzoneConsts.S3_BUCKET, OzoneConsts.KEY, content.length(), 1, uploadID, null, null, body);
            fail("Should throw IOException");
        } catch (IOException ignored) {
            // Verify that the message digest is reset so that the instance can be reused for the
            // next request in the same thread
            verify(messageDigest, times(1)).reset();
        }
    }
}

