@Test
public void testReportAPIs() {
    OzoneConfiguration conf = new OzoneConfiguration();
    DatanodeStateMachine datanodeStateMachineMock = mock(DatanodeStateMachine.class);
    StateContext stateContext = new StateContext(conf, DatanodeStates.getInitState(), datanodeStateMachineMock, "");
    InetSocketAddress scm1 = new InetSocketAddress("scm1", 9001);
    InetSocketAddress scm2 = new InetSocketAddress("scm2", 9001);
    Message generatedMessage = newMockReport(StateContext.COMMAND_STATUS_REPORTS_PROTO_NAME);
    // Try to add report with zero endpoint. Should not be stored.
    stateContext.addIncrementalReport(generatedMessage);
    assertTrue(stateContext.getAllAvailableReports(scm1).isEmpty());
    // Add 2 scm endpoints.
    stateContext.addEndpoint(scm1);
    stateContext.addEndpoint(scm2);
    // Add report. Should be added to all endpoints.
    stateContext.addIncrementalReport(generatedMessage);
    List<Message> allAvailableReports = stateContext.getAllAvailableReports(scm1);
    assertEquals(1, allAvailableReports.size());
    assertEquals(1, stateContext.getAllAvailableReports(scm2).size());
    // Assert the reports are no longer available.
    assertTrue(stateContext.getAllAvailableReports(scm1).isEmpty());
    // Put back reports.
    stateContext.putBackReports(allAvailableReports, scm1);
    assertFalse(stateContext.getAllAvailableReports(scm1).isEmpty());
}

@Test
public void testGetReports() {
    OzoneConfiguration conf = new OzoneConfiguration();
    DatanodeStateMachine datanodeStateMachineMock = mock(DatanodeStateMachine.class);
    StateContext ctx = new StateContext(conf, DatanodeStates.getInitState(), datanodeStateMachineMock, "");
    InetSocketAddress scm1 = new InetSocketAddress("scm1", 9001);
    ctx.addEndpoint(scm1);
    InetSocketAddress scm2 = new InetSocketAddress("scm2", 9001);
    ctx.addEndpoint(scm2);
    // Check initial state
    assertEquals(0, ctx.getAllAvailableReports(scm1).size());
    assertEquals(0, ctx.getAllAvailableReports(scm2).size());
    Map<String, Integer> expectedReportCount = new HashMap<>();
    int totalIncrementalCount = 128;
    // Add a bunch of ContainerReports
    batchRefreshfullReports(ctx, StateContext.CONTAINER_REPORTS_PROTO_NAME, totalIncrementalCount);
    batchRefreshfullReports(ctx, StateContext.NODE_REPORT_PROTO_NAME, totalIncrementalCount);
    batchRefreshfullReports(ctx, StateContext.PIPELINE_REPORTS_PROTO_NAME, totalIncrementalCount);
    batchAddIncrementalReport(ctx, StateContext.INCREMENTAL_CONTAINER_REPORT_PROTO_NAME, totalIncrementalCount);
    // Should only keep the latest one
    expectedReportCount.put(StateContext.CONTAINER_REPORTS_PROTO_NAME, 1);
    expectedReportCount.put(StateContext.NODE_REPORT_PROTO_NAME, 1);
    expectedReportCount.put(StateContext.PIPELINE_REPORTS_PROTO_NAME, 1);
    // Should keep less or equal than maxLimit depending on other reports' size.
    // Here, the incremental container reports count must be 97
    // (100 - 3 non-incremental reports)
    expectedReportCount.put(StateContext.INCREMENTAL_CONTAINER_REPORT_PROTO_NAME, 97);
    checkReportCount(ctx.getAllAvailableReportsUpToLimit(scm1, 100), expectedReportCount);
    checkReportCount(ctx.getAllAvailableReportsUpToLimit(scm2, 100), expectedReportCount);
    expectedReportCount.clear();
    expectedReportCount.put(StateContext.INCREMENTAL_CONTAINER_REPORT_PROTO_NAME, totalIncrementalCount - 97);
    checkReportCount(ctx.getAllAvailableReportsUpToLimit(scm1, 100), expectedReportCount);
    checkReportCount(ctx.getAllAvailableReportsUpToLimit(scm2, 100), expectedReportCount);
}

@Test
public void testPutObjectMessageDigestResetDuringException() throws OS3Exception {
    MessageDigest messageDigest = mock(MessageDigest.class);
    try (MockedStatic<IOUtils> mocked = mockStatic(IOUtils.class)) {
        // For example, EOFException during put-object due to client cancelling the operation before it completes
        mocked.when(() -> IOUtils.copyLarge(any(InputStream.class), any(OutputStream.class), anyLong(), anyLong(), any(byte[].class))).thenThrow(IOException.class);
        when(objectEndpoint.getMessageDigestInstance()).thenReturn(messageDigest);
        ByteArrayInputStream body = new ByteArrayInputStream(CONTENT.getBytes(UTF_8));
        try {
            objectEndpoint.put(BUCKET_NAME, KEY_NAME, CONTENT.length(), 1, null, null, null, body);
            fail("Should throw IOException");
        } catch (IOException ignored) {
            // Verify that the message digest is reset so that the instance can be reused for the
            // next request in the same thread
            verify(messageDigest, times(1)).reset();
        }
    }
}

