    OmKeyInfo currentKey4 = getMockedOmKeyInfo(bucketInfo, 8, "key4", 4);
    Table<String, OmKeyInfo> prevKeyTable = new InMemoryTestTable<>(ImmutableMap.of(getDirectoryKey(volumeId, bucketInfo, prevKey), prevKey, getDirectoryKey(volumeId, bucketInfo, prevKey2), prevKey2));
