@Test
public void testUnknownRequestHandling() throws IOException, ServiceException {
    // Create an instance of OMRequest with an unknown command type.
    OzoneManagerProtocolProtos.OMRequest omRequest = OzoneManagerProtocolProtos.OMRequest.newBuilder().setCmdType(OzoneManagerProtocolProtos.Type.UnknownCommand).setClientId("test-client-id").build();
    ozoneManager = mock(OzoneManager.class);
    ozoneConfiguration.set(OMConfigKeys.OZONE_OM_DB_DIRS, folder.resolve("om").toAbsolutePath().toString());
    OMMetadataManager omMetadataManager = new OmMetadataManagerImpl(ozoneConfiguration, ozoneManager);
    when(ozoneManager.getMetadataManager()).thenReturn(omMetadataManager);
    OMExecutionFlow omExecutionFlow = new OMExecutionFlow(ozoneManager);
    when(ozoneManager.getOmExecutionFlow()).thenReturn(omExecutionFlow);
    when(ozoneManager.getConfiguration()).thenReturn(ozoneConfiguration);
    final OmConfig omConfig = ozoneConfiguration.getObject(OmConfig.class);
    when(ozoneManager.getConfig()).thenReturn(omConfig);
    OzoneManagerRatisServer ratisServer = mock(OzoneManagerRatisServer.class);
    ProtocolMessageMetrics<ProtocolMessageEnum> protocolMessageMetrics = mock(ProtocolMessageMetrics.class);
    OzoneManagerProtocolProtos.OMResponse expectedResponse = OzoneManagerProtocolProtos.OMResponse.newBuilder().setStatus(INVALID_REQUEST).setCmdType(omRequest.getCmdType()).setTraceID(omRequest.getTraceID()).setSuccess(false).setMessage("Unrecognized write command type request " + omRequest.getCmdType()).build();
    OzoneManagerProtocolServerSideTranslatorPB serverSideTranslatorPB = new OzoneManagerProtocolServerSideTranslatorPB(ozoneManager, ratisServer, protocolMessageMetrics);
    OzoneManagerProtocolProtos.OMResponse actualResponse = serverSideTranslatorPB.processRequest(omRequest);
    assertEquals(expectedResponse, actualResponse);
}

