/**
 * Verify that Multi-Tenancy read and write requests are blocked as intended
 * when the feature is disabled.
 */
@Test
public void testMultiTenancyRequestsWhenDisabled() throws IOException {
    final OzoneManager ozoneManager = mock(OzoneManager.class);
    doCallRealMethod().when(ozoneManager).checkS3MultiTenancyEnabled();
    final OzoneConfiguration conf = new OzoneConfiguration();
    when(ozoneManager.getConfiguration()).thenReturn(conf);
    final OmConfig omConfig = conf.getObject(OmConfig.class);
    when(ozoneManager.getConfig()).thenReturn(omConfig);
    when(ozoneManager.isS3MultiTenancyEnabled()).thenReturn(false);
    final String tenantId = "test-tenant";
    final String userPrincipal = "alice";
    final String accessId = OMMultiTenantManager.getDefaultAccessId(tenantId, userPrincipal);
    // Check that Multi-Tenancy write requests are blocked when not enabled
    expectWriteRequestToFail(ozoneManager, OMRequestTestUtils.createTenantRequest(tenantId, false));
    expectWriteRequestToFail(ozoneManager, OMRequestTestUtils.deleteTenantRequest(tenantId));
    expectWriteRequestToFail(ozoneManager, OMRequestTestUtils.tenantAssignUserAccessIdRequest(userPrincipal, tenantId, accessId));
    expectWriteRequestToFail(ozoneManager, OMRequestTestUtils.tenantRevokeUserAccessIdRequest(accessId));
    expectWriteRequestToFail(ozoneManager, OMRequestTestUtils.tenantAssignAdminRequest(accessId, tenantId, true));
    expectWriteRequestToFail(ozoneManager, OMRequestTestUtils.tenantRevokeAdminRequest(accessId, tenantId));
    // Check that Multi-Tenancy read requests are blocked when not enabled
    final OzoneManagerRequestHandler ozoneManagerRequestHandler = new OzoneManagerRequestHandler(ozoneManager);
    expectReadRequestToFail(ozoneManagerRequestHandler, OMRequestTestUtils.listUsersInTenantRequest(tenantId));
    expectReadRequestToFail(ozoneManagerRequestHandler, OMRequestTestUtils.listTenantRequest());
    expectReadRequestToFail(ozoneManagerRequestHandler, OMRequestTestUtils.tenantGetUserInfoRequest(tenantId));
    // getS3VolumeContext request does not throw exception when MT is disabled.
    // Rather, it falls back to the default s3v for backwards compatibility.
}

