            }
        }, 1000, 100000);
        GenericTestUtils.waitFor(() -> {
            try {
                return renameTable.get(omMetadataManager.getRenameKey(testVolumeName, testBucketName, objectId)) == null;
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }, 1000, 10000);
        return i.callRealMethod();
    }).when(omSnapshotManager).getActiveSnapshot(ArgumentMatchers.eq(testVolumeName), ArgumentMatchers.eq(testBucketName), ArgumentMatchers.eq(snap1));
    assertTableRowCount(snapshotInfoTable, initialSnapshotCount + 1);
