        endpoint.delete("fsoBucket", "dir/", null, "");
        fail("Expected an OS3Exception to be thrown");
    } catch (OS3Exception ex) {
        assertEquals(HTTP_NOT_IMPLEMENTED, ex.getHttpCode());
        assertEquals(NOT_IMPLEMENTED.getCode(), ex.getCode());
    }
}

