@ParameterizedTest(name = "schema V3 enabled :{0}")
@ValueSource(booleans = { false, true })
public void testFinalizeFailure(boolean schemaV3Enabled) throws Exception {
    initTests(schemaV3Enabled);
    // start DN and SCM
    scmRpcServer = SCMTestUtils.startScmRpcServer(conf, new ScmTestMock(CLUSTER_ID), address, 10);
    UpgradeTestHelper.addHddsVolume(conf, tempFolder);
    // Let HddsVolume be formatted to mimic the real cluster upgrade
    // Set layout version.
    DatanodeLayoutStorage layoutStorage = new DatanodeLayoutStorage(conf, UUID.randomUUID().toString(), HDDSLayoutFeature.ERASURE_CODED_STORAGE_SUPPORT.layoutVersion());
    layoutStorage.initialize();
    dsm = new DatanodeStateMachine(ContainerTestUtils.createDatanodeDetails(), conf);
    HddsVolume dataVolume = (HddsVolume) dsm.getContainer().getVolumeSet().getVolumesList().get(0);
    // Format HddsVolume to mimic the real cluster upgrade situation
    dataVolume.format(CLUSTER_ID);
    File idDir = new File(dataVolume.getStorageDir(), CLUSTER_ID);
    if (!idDir.mkdir()) {
        fail("Failed to create id directory");
    }
    assertNull(dataVolume.getDbParentDir());
    // Restart DN
    dsm = UpgradeTestHelper.restartDatanode(conf, dsm, false, tempFolder, address, HDDSLayoutFeature.ERASURE_CODED_STORAGE_SUPPORT.layoutVersion(), true);
    ContainerDispatcher dispatcher = dsm.getContainer().getDispatcher();
    // Write some data.
    final Pipeline pipeline = MockPipeline.createPipeline(Collections.singletonList(dsm.getDatanodeDetails()));
    final long containerID = UpgradeTestHelper.addContainer(dispatcher, pipeline);
    ContainerProtos.WriteChunkRequestProto writeChunk = UpgradeTestHelper.putBlock(dispatcher, containerID, pipeline);
    UpgradeTestHelper.closeContainer(dispatcher, containerID, pipeline);
    KeyValueContainer container = (KeyValueContainer) dsm.getContainer().getContainerSet().getContainer(containerID);
    assertEquals(OzoneConsts.SCHEMA_V2, container.getContainerData().getSchemaVersion());
    HddsVolume volume = mock(HddsVolume.class);
    doThrow(new IOException("Failed to init DB")).when(volume).createDbStore(any());
    Map volumeMap = new HashMap<String, StorageVolume>();
    volumeMap.put(dataVolume.getStorageID(), volume);
    dsm.getContainer().getVolumeSet().setVolumeMap(volumeMap);
    // Finalize will fail because of DB creation failure
    try {
        dsm.finalizeUpgrade();
    } catch (Exception e) {
        // Currently there will be retry if finalization failed.
        // Let's assume retry is terminated by user.
    }
    // Check that old data is readable
    container = (KeyValueContainer) dsm.getContainer().getContainerSet().getContainer(containerID);
    assertEquals(OzoneConsts.SCHEMA_V2, container.getContainerData().getSchemaVersion());
    UpgradeTestHelper.readChunk(dispatcher, writeChunk, pipeline);
    // SchemaV3 is not finalized, so still ERASURE_CODED_STORAGE_SUPPORT
    dsm = UpgradeTestHelper.restartDatanode(conf, dsm, false, tempFolder, address, HDDSLayoutFeature.ERASURE_CODED_STORAGE_SUPPORT.layoutVersion(), true);
    dispatcher = dsm.getContainer().getDispatcher();
    // Old data is readable after DN restart
    container = (KeyValueContainer) dsm.getContainer().getContainerSet().getContainer(containerID);
    assertEquals(OzoneConsts.SCHEMA_V2, container.getContainerData().getSchemaVersion());
    UpgradeTestHelper.readChunk(dispatcher, writeChunk, pipeline);
}

