@Test
public void testCreateContainerWithFailure() throws Exception {
    final String testDir = tempDir.toString();
    final long containerID = 1L;
    final String clusterId = UUID.randomUUID().toString();
    final String datanodeId = UUID.randomUUID().toString();
    conf = new OzoneConfiguration();
    final ContainerSet containerSet = spy(newContainerSet());
    final MutableVolumeSet volumeSet = mock(MutableVolumeSet.class);
    HddsVolume hddsVolume = new HddsVolume.Builder(testDir).conf(conf).clusterID(clusterId).datanodeUuid(datanodeId).volumeSet(volumeSet).build();
    hddsVolume.format(clusterId);
    hddsVolume.createWorkingDir(clusterId, null);
    hddsVolume.createTmpDirs(clusterId);
    when(volumeSet.getVolumesList()).thenReturn(Collections.singletonList(hddsVolume));
    List<HddsVolume> hddsVolumeList = StorageVolumeUtil.getHddsVolumesList(volumeSet.getVolumesList());
    assertEquals(1, hddsVolumeList.size());
    final ContainerMetrics metrics = ContainerMetrics.create(conf);
    final AtomicInteger icrReceived = new AtomicInteger(0);
    final KeyValueHandler kvHandler = new KeyValueHandler(conf, datanodeId, containerSet, volumeSet, metrics, c -> icrReceived.incrementAndGet(), new ContainerChecksumTreeManager(conf));
    kvHandler.setClusterID(clusterId);
    final ContainerCommandRequestProto createContainer = createContainerRequest(datanodeId, containerID);
    Semaphore semaphore = new Semaphore(1);
    doAnswer(invocation -> {
        semaphore.acquire();
        throw new StorageContainerException(ContainerProtos.Result.IO_EXCEPTION);
    }).when(containerSet).addContainer(any());
    semaphore.acquire();
    CompletableFuture.runAsync(() -> kvHandler.handleCreateContainer(createContainer, null));
    // commit bytes has been allocated by volumeChoosingPolicy which is called in KeyValueContainer#create
    GenericTestUtils.waitFor(() -> hddsVolume.getCommittedBytes() == maxContainerSize, 1000, 50000);
    semaphore.release();
    LOG.info("Committed bytes: {}", hddsVolume.getCommittedBytes());
    // release committed bytes as exception is thrown
    GenericTestUtils.waitFor(() -> hddsVolume.getCommittedBytes() == 0, 1000, 50000);
}

