public void testProcessLayoutVersionReportHigherMlv(FinalizationCheckpoint currentCheckpoint) throws IOException {
    // milliseconds
    final int healthCheckInterval = 200;
    // seconds
    final int heartbeatInterval = 1;
    OzoneConfiguration conf = getConf();
    conf.setTimeDuration(OZONE_SCM_HEARTBEAT_PROCESS_INTERVAL, healthCheckInterval, MILLISECONDS);
    conf.setTimeDuration(HDDS_HEARTBEAT_INTERVAL, heartbeatInterval, SECONDS);
    SCMStorageConfig scmStorageConfig = mock(SCMStorageConfig.class);
    when(scmStorageConfig.getClusterID()).thenReturn("xyz111");
    EventPublisher eventPublisher = mock(EventPublisher.class);
    HDDSLayoutVersionManager lvm = new HDDSLayoutVersionManager(scmStorageConfig.getLayoutVersion());
    SCMContext nodeManagerContext = SCMContext.emptyContext();
    nodeManagerContext.setFinalizationCheckpoint(currentCheckpoint);
    SCMNodeManager nodeManager = new SCMNodeManager(conf, scmStorageConfig, eventPublisher, new NetworkTopologyImpl(conf), nodeManagerContext, lvm);
    // Regardless of SCM's finalization checkpoint, datanodes with higher MLV
    // than SCM should not be found in the cluster.
    DatanodeDetails node1 = HddsTestUtils.createRandomDatanodeAndRegister(nodeManager);
    LogCapturer logCapturer = LogCapturer.captureLogs(SCMNodeManager.class);
    int scmMlv = nodeManager.getLayoutVersionManager().getMetadataLayoutVersion();
    int scmSlv = nodeManager.getLayoutVersionManager().getSoftwareLayoutVersion();
    nodeManager.processLayoutVersionReport(node1, LayoutVersionProto.newBuilder().setMetadataLayoutVersion(scmMlv + 1).setSoftwareLayoutVersion(scmSlv + 1).build());
    assertThat(logCapturer.getOutput()).contains("Invalid data node in the cluster");
    nodeManager.close();
}

