@Test
public void testSuccessWhenDecommissionStatus() throws IOException {
    ScmClient scmClient = mock(ScmClient.class);
    when(scmClient.queryNode(any(), any(), any(), any())).thenAnswer(// 2 nodes decommissioning
    invocation -> nodes);
    when(scmClient.getContainersOnDecomNode(any())).thenReturn(containerOnDecom);
    when(scmClient.getMetrics(any())).thenReturn(metrics.get(1));
    CommandLine cmdLine = new CommandLine(cmd);
    cmdLine.parseArgs();
    cmd.execute(scmClient);
    Pattern p = Pattern.compile("Decommission\\sStatus:\\s" + "DECOMMISSIONING\\s-\\s2\\snode\\(s\\)\n");
    Matcher m = p.matcher(outContent.toString(DEFAULT_ENCODING));
    assertTrue(m.find());
    // Both DN details are shown
    p = Pattern.compile("Datanode:\\s.*host0\\)");
    m = p.matcher(outContent.toString(DEFAULT_ENCODING));
    assertTrue(m.find());
    p = Pattern.compile("Datanode:\\s.*host1\\)");
    m = p.matcher(outContent.toString(DEFAULT_ENCODING));
    assertTrue(m.find());
    p = Pattern.compile("No\\. of Unclosed Pipelines:");
    m = p.matcher(outContent.toString(DEFAULT_ENCODING));
    assertTrue(m.find());
    // metrics for both are shown
    assertTrue(m.find());
    p = Pattern.compile("UnderReplicated=.* UnClosed=");
    m = p.matcher(outContent.toString(DEFAULT_ENCODING));
    assertTrue(m.find());
    // container lists for both are shown
    assertTrue(m.find());
}

