public void testUsedOrderingAndOutput(boolean mostUsed, String cliFlag, String orderDirection) throws Exception {
    ScmClient scmClient = mock(ScmClient.class);
    List<HddsProtos.DatanodeUsageInfoProto> usageList = new ArrayList<>();
    List<HddsProtos.Node> nodeList = getNodeDetails();
    for (int i = 0; i < 4; i++) {
        long remaining = 1000 - (100 * i);
        usageList.add(HddsProtos.DatanodeUsageInfoProto.newBuilder().setNode(nodeList.get(i).getNodeID()).setRemaining(remaining).setCapacity(1000).build());
        when(scmClient.queryNode(UUID.fromString(nodeList.get(i).getNodeID().getUuid()))).thenReturn(nodeList.get(i));
    }
    if (mostUsed) {
        // For most-used only
        Collections.reverse(usageList);
    }
    when(scmClient.getDatanodeUsageInfo(mostUsed, Integer.MAX_VALUE)).thenReturn(usageList);
    when(scmClient.listPipelines()).thenReturn(new ArrayList<>());
