public void connectsToNewPipeline() throws Exception {
    // GIVEN
    Pipeline pipeline = MockPipeline.createSingleNodePipeline();
    Pipeline newPipeline = MockPipeline.createSingleNodePipeline();
    Token<?> token = mock(Token.class);
    when(token.encodeToUrlString()).thenReturn("oldToken");
    Token<?> newToken = mock(Token.class);
    when(newToken.encodeToUrlString()).thenReturn("newToken");
    AtomicReference<Pipeline> pipelineRef = new AtomicReference<>(pipeline);
    AtomicReference<Token<?>> tokenRef = new AtomicReference<>(token);
    XceiverClientFactory clientFactory = mock(XceiverClientFactory.class);
    XceiverClientSpi client = mock(XceiverClientSpi.class);
    when(clientFactory.acquireClientForReadData(any())).thenReturn(client);
    ArgumentCaptor<ContainerCommandRequestProto> requestCaptor = ArgumentCaptor.forClass(ContainerCommandRequestProto.class);
    when(client.getPipeline()).thenAnswer(invocation -> pipelineRef.get());
    when(client.sendCommand(requestCaptor.capture(), any())).thenAnswer(invocation -> getReadChunkResponse(requestCaptor.getValue(), ChunkBuffer.wrap(ByteBuffer.wrap(chunkData)), ByteStringConversion::safeWrap));
    try (ChunkInputStream subject = new ChunkInputStream(chunkInfo, blockID, clientFactory, pipelineRef::get, false, tokenRef::get)) {
        // WHEN
