    PipelineManager pipelineManager = mock(PipelineManager.class);
    // After finalization, SCM will wait for at least one pipeline to be
    // created. It does not care about the contents of the pipeline list, so
    // just return something with length >= 1.
    when(pipelineManager.getPipelines(any(), any())).thenReturn(Arrays.asList(null, null, null));
    // Set the initial value for pipeline creation based on the checkpoint.
    // In a real cluster, this would be set on startup of the
    // PipelineManagerImpl.
    pipelineCreationFrozen = !FinalizationManager.shouldCreateNewPipelines(inititalCheckpoint);
    doAnswer(args -> pipelineCreationFrozen = true).when(pipelineManager).freezePipelineCreation();
    doAnswer(args -> pipelineCreationFrozen = false).when(pipelineManager).resumePipelineCreation();
    doAnswer(args -> pipelineCreationFrozen).when(pipelineManager).isPipelineCreationFrozen();
    return pipelineManager;
}

