@ContainerLayoutTestInfo.ContainerTest
public void testReplicationImportReserveSpace(ContainerLayoutVersion layout) throws IOException, InterruptedException, TimeoutException {
    final long containerUsedSize = 100;
    this.layoutVersion = layout;
    OzoneConfiguration conf = new OzoneConfiguration();
    conf.set(ScmConfigKeys.HDDS_DATANODE_DIR_KEY, tempDir.getAbsolutePath());
    long containerMaxSize = (long) conf.getStorageSize(ScmConfigKeys.OZONE_SCM_CONTAINER_SIZE, ScmConfigKeys.OZONE_SCM_CONTAINER_SIZE_DEFAULT, StorageUnit.BYTES);
    ReplicationSupervisor supervisor = ReplicationSupervisor.newBuilder().stateContext(context).executor(newDirectExecutorService()).clock(clock).build();
    MutableVolumeSet volumeSet = new MutableVolumeSet(datanode.getUuidString(), conf, null, StorageVolume.VolumeType.DATA_VOLUME, null);
    long containerId = 1;
    // create container
    KeyValueContainerData containerData = new KeyValueContainerData(containerId, ContainerLayoutVersion.FILE_PER_BLOCK, containerMaxSize, "test", "test");
    HddsVolume vol1 = (HddsVolume) volumeSet.getVolumesList().get(0);
    containerData.setVolume(vol1);
    // the container is not yet in HDDS, so only set its own size, leaving HddsVolume with used=0
    containerData.getStatistics().updateWrite(100, false);
    KeyValueContainer container = new KeyValueContainer(containerData, conf);
    ContainerController controllerMock = mock(ContainerController.class);
    Semaphore semaphore = new Semaphore(1);
    when(controllerMock.importContainer(any(), any(), any())).thenAnswer((invocation) -> {
        semaphore.acquire();
        return container;
    });
    File tarFile = containerTarFile(containerId, containerData);
    SimpleContainerDownloader moc = mock(SimpleContainerDownloader.class);
    when(moc.getContainerDataFromReplicas(anyLong(), anyList(), any(Path.class), any())).thenReturn(tarFile.toPath());
    ContainerImporter importer = new ContainerImporter(conf, set, controllerMock, volumeSet, volumeChoosingPolicy);
    // Initially volume has 0 commit space
    assertEquals(0, vol1.getCommittedBytes());
    long usedSpace = vol1.getCurrentUsage().getUsedSpace();
    // Initially volume has 0 used space
    assertEquals(0, usedSpace);
    // Increase committed bytes so that volume has only remaining 3 times container size space
    long minFreeSpace = conf.getObject(DatanodeConfiguration.class).getMinFreeSpace(vol1.getCurrentUsage().getCapacity());
    long initialCommittedBytes = vol1.getCurrentUsage().getCapacity() - containerMaxSize * 3 - minFreeSpace;
    vol1.incCommittedBytes(initialCommittedBytes);
    ContainerReplicator replicator = new DownloadAndImportReplicator(conf, set, importer, moc);
    replicatorRef.set(replicator);
    LogCapturer logCapturer = LogCapturer.captureLogs(DownloadAndImportReplicator.class);
    // Acquire semaphore so that container import will pause after reserving space.
    semaphore.acquire();
    CompletableFuture.runAsync(() -> {
        try {
            supervisor.addTask(createTask(containerId));
        } catch (Exception ex) {
        }
    });
    // Wait such that first container import reserve space
