 * Tests that only QUEUED jobs are submitted to the executor and rest are
 * short-circuited based on previous one.
 */
@Test
public void testGetSnapshotDiffReportJob() throws Exception {
    for (int i = 0; i < jobStatuses.size(); i++) {
        uploadSnapshotDiffJobToDb(snapshotInfo, snapshotInfoList.get(i), snapDiffJobs.get(i));
    }
    SnapshotDiffManager spy = spy(snapshotDiffManager);
    doAnswer(invocation -> {
        SnapshotDiffJob diffJob = getSnapshotDiffJobFromDb(snapshotInfo, snapshotInfoList.get(0));
        diffJob.setTotalDiffEntries(1L);
        diffJob.setStatus(DONE);
        uploadSnapshotDiffJobToDb(snapshotInfo, snapshotInfoList.get(0), diffJob);
        return null;
    }).when(spy).generateSnapshotDiffReport(anyString(), anyString(), eq(VOLUME_NAME), eq(BUCKET_NAME), eq(snapshotInfo.getName()), eq(snapshotInfoList.get(0).getName()), eq(false), eq(false));
    for (int i = 0; i < snapshotInfoList.size(); i++) {
        SnapshotDiffResponse snapshotDiffReport = spy.getSnapshotDiffReport(VOLUME_NAME, BUCKET_NAME, snapshotInfo.getName(), snapshotInfoList.get(i).getName(), 0, 1000, false, false);
        SnapshotDiffJob diffJob = snapDiffJobs.get(i);
        if (diffJob.getStatus() == QUEUED) {
            assertEquals(IN_PROGRESS, snapshotDiffReport.getJobStatus());
        } else {
            assertEquals(diffJob.getStatus(), snapshotDiffReport.getJobStatus());
        }
    }
}

