@Test
public void testRun() throws Exception {
    UnhealthyContainersDao unHealthyContainersTableHandle = getDao(UnhealthyContainersDao.class);
    ContainerHealthSchemaManager containerHealthSchemaManager = new ContainerHealthSchemaManager(getSchemaDefinition(ContainerSchemaDefinition.class), unHealthyContainersTableHandle);
    ReconStorageContainerManagerFacade scmMock = mock(ReconStorageContainerManagerFacade.class);
    ReconContainerMetadataManager reconContainerMetadataManager = mock(ReconContainerMetadataManager.class);
    MockPlacementPolicy placementMock = new MockPlacementPolicy();
    ContainerManager containerManagerMock = mock(ContainerManager.class);
    StorageContainerServiceProvider scmClientMock = mock(StorageContainerServiceProvider.class);
    ContainerReplica unhealthyReplicaMock = mock(ContainerReplica.class);
    when(unhealthyReplicaMock.getState()).thenReturn(State.UNHEALTHY);
    ContainerReplica healthyReplicaMock = mock(ContainerReplica.class);
    when(healthyReplicaMock.getState()).thenReturn(State.CLOSED);
    // Create 7 containers. The first 5 will have various unhealthy states
    // defined below. The container with ID=6 will be healthy and
    // container with ID=7 will be EMPTY_MISSING (but not inserted into DB)
    List<ContainerInfo> mockContainers = getMockContainers(8);
    when(scmMock.getScmServiceProvider()).thenReturn(scmClientMock);
    when(scmMock.getContainerManager()).thenReturn(containerManagerMock);
    when(containerManagerMock.getContainers(any(ContainerID.class), anyInt())).thenReturn(mockContainers);
    for (ContainerInfo c : mockContainers) {
        when(containerManagerMock.getContainer(c.containerID())).thenReturn(c);
        when(scmClientMock.getContainerWithPipeline(c.getContainerID())).thenReturn(new ContainerWithPipeline(c, null));
    }
    ReplicatedReplicationConfig replicationConfig = RatisReplicationConfig.getInstance(THREE);
    // Under replicated
    ContainerInfo containerInfo1 = TestContainerInfo.newBuilderForTest().setContainerID(1).setReplicationConfig(replicationConfig).build();
    when(containerManagerMock.getContainer(ContainerID.valueOf(1L))).thenReturn(containerInfo1);
    when(containerManagerMock.getContainerReplicas(containerInfo1.containerID())).thenReturn(getMockReplicas(1L, State.CLOSED, State.UNHEALTHY));
    // return all UNHEALTHY replicas for container ID 2 -> UNDER_REPLICATED
    ContainerInfo containerInfo2 = TestContainerInfo.newBuilderForTest().setContainerID(2).setReplicationConfig(replicationConfig).build();
    when(containerManagerMock.getContainer(ContainerID.valueOf(2L))).thenReturn(containerInfo2);
    when(containerManagerMock.getContainerReplicas(containerInfo2.containerID())).thenReturn(getMockReplicas(2L, State.UNHEALTHY));
    // return 0 replicas for container ID 3 -> EMPTY_MISSING (will not be inserted into DB)
    ContainerInfo containerInfo3 = TestContainerInfo.newBuilderForTest().setContainerID(3).setReplicationConfig(replicationConfig).build();
    when(containerManagerMock.getContainer(ContainerID.valueOf(3L))).thenReturn(containerInfo3);
    when(containerManagerMock.getContainerReplicas(containerInfo3.containerID())).thenReturn(Collections.emptySet());
    // Return 5 Healthy Replicas -> Over-replicated
    ContainerInfo containerInfo4 = TestContainerInfo.newBuilderForTest().setContainerID(4).setReplicationConfig(replicationConfig).build();
    when(containerManagerMock.getContainer(ContainerID.valueOf(4L))).thenReturn(containerInfo4);
    when(containerManagerMock.getContainerReplicas(containerInfo4.containerID())).thenReturn(getMockReplicas(4L, State.CLOSED, State.CLOSED, State.CLOSED, State.CLOSED, State.CLOSED));
    // Mis-replicated
    ContainerInfo containerInfo5 = TestContainerInfo.newBuilderForTest().setContainerID(5).setReplicationConfig(replicationConfig).build();
    when(containerManagerMock.getContainer(ContainerID.valueOf(5L))).thenReturn(containerInfo5);
    Set<ContainerReplica> misReplicas = getMockReplicas(5L, State.CLOSED, State.CLOSED, State.CLOSED);
    placementMock.setMisRepWhenDnPresent(misReplicas.iterator().next().getDatanodeDetails().getUuid());
    when(containerManagerMock.getContainerReplicas(containerInfo5.containerID())).thenReturn(misReplicas);
    // Return 3 Healthy Replicas -> Healthy container
    ContainerInfo containerInfo6 = TestContainerInfo.newBuilderForTest().setContainerID(6).setReplicationConfig(replicationConfig).build();
    when(containerManagerMock.getContainer(ContainerID.valueOf(6L))).thenReturn(containerInfo6);
    when(containerManagerMock.getContainerReplicas(containerInfo6.containerID())).thenReturn(getMockReplicas(6L, State.CLOSED, State.CLOSED, State.CLOSED));
    // return 0 replicas for container ID 7 -> MISSING (will later transition to EMPTY_MISSING but not inserted into DB)
    ContainerInfo containerInfo7 = TestContainerInfo.newBuilderForTest().setContainerID(7).setReplicationConfig(replicationConfig).build();
    when(containerManagerMock.getContainer(ContainerID.valueOf(7L))).thenReturn(containerInfo7);
    when(containerManagerMock.getContainerReplicas(containerInfo7.containerID())).thenReturn(Collections.emptySet());
    when(reconContainerMetadataManager.getKeyCountForContainer(7L)).thenReturn(// Indicates non-empty container 7 for now
    5L);
    // container ID 8 - REPLICA_MISMATCH
    ContainerInfo containerInfo8 = TestContainerInfo.newBuilderForTest().setContainerID(8).setReplicationConfig(replicationConfig).build();
    when(containerManagerMock.getContainer(ContainerID.valueOf(8L))).thenReturn(containerInfo8);
    Set<ContainerReplica> mismatchReplicas = getMockReplicasChecksumMismatch(8L, State.CLOSED, State.CLOSED, State.CLOSED);
    when(containerManagerMock.getContainerReplicas(containerInfo8.containerID())).thenReturn(mismatchReplicas);
    List<UnhealthyContainers> all = unHealthyContainersTableHandle.findAll();
    assertThat(all).isEmpty();
    long currentTime = System.currentTimeMillis();
    ReconTaskStatusDao reconTaskStatusDao = getDao(ReconTaskStatusDao.class);
    ReconTaskConfig reconTaskConfig = new ReconTaskConfig();
    reconTaskConfig.setMissingContainerTaskInterval(Duration.ofSeconds(10));
    // Start container health task
    ContainerHealthTask containerHealthTask = new ContainerHealthTask(scmMock.getContainerManager(), scmMock.getScmServiceProvider(), containerHealthSchemaManager, placementMock, reconTaskConfig, reconContainerMetadataManager, new OzoneConfiguration(), getMockTaskStatusUpdaterManager());
    containerHealthTask.start();
    // Ensure unhealthy container count in DB matches expected
    LambdaTestUtils.await(60000, 1000, () -> (unHealthyContainersTableHandle.count() == 6));
    // Check for UNDER_REPLICATED container states
    UnhealthyContainers rec = unHealthyContainersTableHandle.fetchByContainerId(1L).get(0);
    assertEquals("UNDER_REPLICATED", rec.getContainerState());
    assertEquals(2, rec.getReplicaDelta().intValue());
    rec = unHealthyContainersTableHandle.fetchByContainerId(2L).get(0);
    assertEquals("UNDER_REPLICATED", rec.getContainerState());
    assertEquals(3, rec.getReplicaDelta().intValue());
    // Assert that EMPTY_MISSING state containers were never added to DB.
    assertEquals(0, unHealthyContainersTableHandle.fetchByContainerId(3L).size());
    List<UnhealthyContainers> unhealthyContainers = containerHealthSchemaManager.getUnhealthyContainers(ALL_REPLICAS_BAD, 0L, Optional.empty(), Integer.MAX_VALUE);
    assertEquals(1, unhealthyContainers.size());
    assertEquals(2L, unhealthyContainers.get(0).getContainerId().longValue());
    assertEquals(0, unhealthyContainers.get(0).getActualReplicaCount().intValue());
    // Check for MISSING state in container ID 7
    rec = unHealthyContainersTableHandle.fetchByContainerId(7L).get(0);
    assertEquals("MISSING", rec.getContainerState());
    assertEquals(3, rec.getReplicaDelta().intValue());
    Field field = ContainerHealthTask.class.getDeclaredField("containerHealthMetrics");
    field.setAccessible(true);
    // Read private field value
    ContainerHealthMetrics containerHealthMetrics = (ContainerHealthMetrics) field.get(containerHealthTask);
    // Only Container ID: 7 is MISSING, so count of missing container count metrics should be equal to 1
    assertEquals(1, containerHealthMetrics.getMissingContainerCount());
    // Container ID: 1 and Container ID: 2, both are UNDER_REPLICATED, so UNDER_REPLICATED
    // container count metric should be 2
    assertEquals(2, containerHealthMetrics.getUnderReplicatedContainerCount());
    rec = unHealthyContainersTableHandle.fetchByContainerId(4L).get(0);
    assertEquals("OVER_REPLICATED", rec.getContainerState());
    assertEquals(-2, rec.getReplicaDelta().intValue());
    rec = unHealthyContainersTableHandle.fetchByContainerId(5L).get(0);
    assertEquals("MIS_REPLICATED", rec.getContainerState());
    assertEquals(1, rec.getReplicaDelta().intValue());
    assertEquals(2, rec.getExpectedReplicaCount().intValue());
