public void setup(TestInfo testInfo) throws IOException, NodeNotFoundException, TimeoutException {
    conf = new OzoneConfiguration();
    ReplicationManagerConfiguration rmConf = new ReplicationManagerConfiguration();
    scm = mock(StorageContainerManager.class);
    ContainerManager containerManager = mock(ContainerManager.class);
    ReplicationManager replicationManager = mock(ReplicationManager.class);
    StatefulServiceStateManager serviceStateManager = mock(StatefulServiceStateManagerImpl.class);
    SCMServiceManager scmServiceManager = mock(SCMServiceManager.class);
    moveManager = mock(MoveManager.class);
    when(moveManager.move(any(ContainerID.class), any(DatanodeDetails.class), any(DatanodeDetails.class))).thenReturn(CompletableFuture.completedFuture(MoveManager.MoveResult.COMPLETED));
    when(replicationManager.getConfig()).thenReturn(rmConf);
    // these configs will usually be specified in each test
    balancerConfiguration = conf.getObject(ContainerBalancerConfiguration.class);
    balancerConfiguration.setThreshold(10);
    balancerConfiguration.setIterations(1);
    balancerConfiguration.setMaxDatanodesPercentageToInvolvePerIteration(100);
    balancerConfiguration.setMaxSizeToMovePerIteration(50 * STORAGE_UNIT);
    balancerConfiguration.setMaxSizeEnteringTarget(50 * STORAGE_UNIT);
    conf.setFromObject(balancerConfiguration);
    GenericTestUtils.setLogLevel(ContainerBalancerTask.class, Level.DEBUG);
    int[] sizeArray = testInfo.getTestMethod().filter(method -> method.getName().equals("balancerShouldMoveOnlyPositiveSizeContainers")).map(method -> new int[] { 0, 0, 0, 0, 0, 1, 2, 3, 4, 5 }).orElse(null);
    createCluster(sizeArray);
    MockNodeManager mockNodeManager = new MockNodeManager(datanodeToContainersMap);
    NetworkTopology clusterMap = mockNodeManager.getClusterNetworkTopologyMap();
    PlacementPolicy placementPolicy = ContainerPlacementPolicyFactory.getPolicy(conf, mockNodeManager, clusterMap, true, SCMContainerPlacementMetrics.create());
    PlacementPolicy ecPlacementPolicy = ContainerPlacementPolicyFactory.getECPolicy(conf, mockNodeManager, clusterMap, true, SCMContainerPlacementMetrics.create());
    PlacementPolicyValidateProxy placementPolicyValidateProxy = new PlacementPolicyValidateProxy(placementPolicy, ecPlacementPolicy);
    when(replicationManager.isContainerReplicatingOrDeleting(any(ContainerID.class))).thenReturn(false);
    when(replicationManager.getClock()).thenReturn(Clock.system(ZoneId.systemDefault()));
    when(containerManager.getContainerReplicas(any(ContainerID.class))).thenAnswer(invocationOnMock -> {
        ContainerID cid = (ContainerID) invocationOnMock.getArguments()[0];
        return cidToReplicasMap.get(cid);
    });
    when(containerManager.getContainer(any(ContainerID.class))).thenAnswer(invocationOnMock -> {
        ContainerID cid = (ContainerID) invocationOnMock.getArguments()[0];
        return cidToInfoMap.get(cid);
    });
    when(containerManager.getContainers()).thenReturn(new ArrayList<>(cidToInfoMap.values()));
    when(scm.getScmNodeManager()).thenReturn(mockNodeManager);
    when(scm.getContainerPlacementPolicy()).thenReturn(placementPolicy);
    when(scm.getContainerManager()).thenReturn(containerManager);
    when(scm.getReplicationManager()).thenReturn(replicationManager);
    when(scm.getScmContext()).thenReturn(SCMContext.emptyContext());
    when(scm.getClusterMap()).thenReturn(null);
