    assertEquals("REPLICA_MISMATCH", rec.getContainerState());
    assertEquals(0, rec.getReplicaDelta().intValue());
    assertEquals(3, rec.getExpectedReplicaCount().intValue());
    assertEquals(3, rec.getActualReplicaCount().intValue());
