    balancerConfiguration = conf.getObject(ContainerBalancerConfiguration.class);
    balancerConfiguration.setThreshold(10);
    balancerConfiguration.setIterations(1);
    balancerConfiguration.setMaxDatanodesPercentageToInvolvePerIteration(100);
    balancerConfiguration.setMaxSizeToMovePerIteration(50 * STORAGE_UNIT);
    balancerConfiguration.setMaxSizeEnteringTarget(50 * STORAGE_UNIT);
    conf.setFromObject(balancerConfiguration);
    GenericTestUtils.setLogLevel(ContainerBalancerTask.class, Level.DEBUG);
    int[] sizeArray = testInfo.getTestMethod().filter(method -> method.getName().equals("balancerShouldMoveOnlyPositiveSizeContainers")).map(method -> new int[] { 0, 0, 0, 0, 0, 1, 2, 3, 4, 5 }).orElse(null);
    createCluster(sizeArray);
